head.script:
scwin.onpageload = function() {
};



// 이 페이지의 body 컴포넌트 조회
//  body 는 root 요소라 scope 전역으로 등록되지 않으므로 정적 선언된 자식의 parentControl 로 조회한다.
scwin.getBody = function () {
    return grp_inner.parentControl;
};



// 이 페이지의 body 에서 getGenerator() 를 호출하여 결과를 부모(테스트 샘플) 결과창에 출력
//  body 는 Generator 의 직접 자식이 될 수 없으나, Generator 템플릿 안의 wframe 으로 로딩되면
//  parentControl 체인이 body -> wframe -> generator 가 되어 부모 Generator 를 반환한다.
scwin.grp_inner_onclick = function (e) {
    let pObj = scwin.getBody().getGenerator();
    let strMsg = (pObj.getPluginName() == "generator") ? "Generator component" : "Not a Generator component";

    $p.parent().scwin.setInnerResult("wframe 내부 body : " + strMsg + " (반환 pluginName : " + pObj.getPluginName() + ")");
};
